package lk.ac.sliit.ridelink.driver.infrastructure.security;
import com.fasterxml.jackson.databind.ObjectMapper; import jakarta.servlet.http.*; import lk.ac.sliit.ridelink.driver.presentation.exception.ApiErrorResponse; import org.springframework.http.MediaType; import org.springframework.security.core.AuthenticationException; import org.springframework.security.web.AuthenticationEntryPoint; import org.springframework.stereotype.Component; import java.io.IOException; import java.time.Instant; import java.util.List;
@Component public class RestAuthenticationEntryPoint implements AuthenticationEntryPoint { private final ObjectMapper m; public RestAuthenticationEntryPoint(ObjectMapper m){this.m=m;} public void commence(HttpServletRequest req,HttpServletResponse res,AuthenticationException e)throws IOException{res.setStatus(401);res.setContentType(MediaType.APPLICATION_JSON_VALUE);m.writeValue(res.getOutputStream(),new ApiErrorResponse(Instant.now(),401,"Unauthorized","Authentication is required or the token is invalid",req.getRequestURI(),List.of()));} }
